const SESSION_KEY = 'elif-os-session-v1';
const todayKey = () => { const d=new Date(); return new Date(d.getFullYear(),d.getMonth(),d.getDate()).toISOString().slice(0,10); };
const addDays = (d,n) => { const x=new Date(d+'T12:00:00'); x.setDate(x.getDate()+n); return x.toISOString().slice(0,10); };
const fmtDate = d => new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00'));
const uid = () => crypto?.randomUUID?.() || Math.random().toString(36).slice(2)+Date.now().toString(36);
const esc = s => String(s ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = n => '₺'+Number(n||0).toLocaleString('tr-TR',{maximumFractionDigits:0});

