function migrate(s){
  if(!s) return seed;
  // v1.2 arrays → v1.3 objects
  s.tasks=(s.tasks||[]).map(t=>({...t,projectId:t.projectId||'',goalId:t.goalId||'',repeat:t.repeat||'none',subtasks:t.subtasks||[],created:t.created||Date.now()}));
  s.habits=(s.habits||[]).map(h=>({id:h.id||uid(),name:h.name||'habit',icon:h.icon||'✦',frequency:h.frequency||'daily',target:h.target||1,days:h.days||{}}));
  s.studyTasks=s.studyTasks||[]; s.studyMinutes=s.studyMinutes||0; s.studyLog=s.studyLog||{}; s.subjects=(s.subjects||[]).map(x=>Array.isArray(x)?{id:uid(),name:x[0],progress:x[1]}:x); s.notes=s.notes||[]; s.studyBlocks=s.studyBlocks||[];
  s.routines=(s.routines||[]).map(r=>Array.isArray(r)?{id:uid(),name:r[0],icon:r[1]||'✦',frequency:r[2]||'daily',target:1}:r); s.routineLog=s.routineLog||{}; s.waterLog=s.waterLog||{}; s.waterGoal=s.waterGoal||2; s.sleepLogs=s.sleepLogs||{}; s.sleepGoal=s.sleepGoal||8;
  s.entries=(s.entries||[]).map(e=>({...e,category:e.category||e.cat||'other',accountId:e.accountId||'',note:e.note||''})); s.accounts=(s.accounts||[]).map(a=>({...a,id:a.id||uid(),type:a.type||'cash'})); s.categories=(s.categories||[]).map(c=>Array.isArray(c)?{id:uid(),name:c[0],limit:c[1]}:c);
  s.recipes=(s.recipes||[]).map(r=>Array.isArray(r)?{id:uid(),name:r[0],emoji:r[1]||'🍽',time:r[2]||'20 mins',category:r[3]||'main',uses:r[4]||0,ingredients:[]}:r); s.grocery=(s.grocery||[]).map(g=>Array.isArray(g)?{id:uid(),name:g[0],done:!!g[1]}:g); s.ingredients=s.ingredients||[]; s.meals=s.meals||{};
  s.goals=(s.goals||[]).map(g=>Array.isArray(g)?{id:uid(),area:g[0],title:g[1],progress:g[2]||0}:g); s.automations=s.automations||[]; s.automationLog=s.automationLog||{}; s.projects=(s.projects||[]).map(p=>({...p,id:p.id||uid(),goalId:p.goalId||''})); s.priorities=s.priorities||[]; s.journal=s.journal||[]; s.brain=s.brain||''; s.checkins=s.checkins||[];
  return s;
}
let state=migrate(JSON.parse(localStorage.getItem(KEY)||'null'));
function save(){localStorage.setItem(KEY,JSON.stringify(state)); render(); queueCloudSync(); runAutomations();}
function toast(t){const el=$('#toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),1800)}
function nav(page){$$('.page').forEach(x=>x.classList.toggle('active-page',x.id===page));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const label=page==='home'?'Home':document.querySelector(`[data-page="${page}"] span`)?.textContent||page;$('#pageTitle').textContent=label;window.scrollTo({top:0,behavior:'smooth'});$('#sidebar')?.classList.remove('open');}

function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.add('open');setTimeout(()=>$('#modal input, #modal textarea, #modal select')?.focus(),30)}
function closeModal(){$('#modal').classList.remove('open');$('#modalBody').innerHTML=''}
function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,options,value=''){return `<label>${esc(label)}<select name="${esc(name)}">${options.map(o=>`<option value="${esc(o[0])}" ${o[0]===value?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`}
function formModal(title, fields, onSave){openModal(`<span class="eyebrow">ELIF OS</span><h2>${esc(title)}</h2><form id="osForm"><div class="form-grid">${fields.join('')}</div><button class="primary full" type="submit">save</button></form>`);$('#osForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);const v=Object.fromEntries(fd.entries());onSave(v);closeModal();}}

function renderTasks(){
 const now=todayKey(), all=state.tasks, q=($('#taskSearch')?.value||'').toLowerCase();
 $('#taskTodayStat').textContent=all.filter(t=>t.date===now&&!t.done).length;
 $('#taskOverdueStat').textContent=all.filter(t=>t.date<now&&!t.done).length;
 $('#taskCompletionStat').textContent=(all.length?Math.round(all.filter(t=>t.done).length/all.length*100):0)+'%';
 $('#todayTasks').innerHTML=all.filter(t=>t.date===now&&!t.done).slice(0,5).map(t=>`<label><input type="checkbox" data-action="toggle-task" data-id="${t.id}"><span>${esc(t.title)}</span><em>${esc(t.priority)}</em></label>`).join('')||'<div class="empty">nothing urgent. make something meaningful.</div>';
 let filter=window.taskFilter||'today', arr=all.filter(t=>t.title.toLowerCase().includes(q));
 if(filter==='today')arr=arr.filter(t=>t.date===now&&!t.done); else if(filter==='next3')arr=arr.filter(t=>t.date>=now&&t.date<=addDays(now,3)&&!t.done); else if(filter==='next7')arr=arr.filter(t=>t.date>=now&&t.date<=addDays(now,7)&&!t.done); else if(filter==='completed')arr=arr.filter(t=>t.done);
 const sort=$('#taskSort')?.value||'date'; arr.sort((a,b)=>sort==='priority'?({high:0,medium:1,low:2}[a.priority]-({high:0,medium:1,low:2}[b.priority])):sort==='created'?b.created-a.created:a.date.localeCompare(b.date));
 $('#allTasks').innerHTML=arr.map(t=>{const subs=t.subtasks||[], subDone=subs.filter(s=>s.done).length; const project=state.projects.find(p=>p.id===t.projectId);return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" data-action="toggle-task" data-id="${t.id}" ${t.done?'checked':''}><div class="task-main"><b>${esc(t.title)}</b><small>${fmtDate(t.date)} · ${esc(project?.name||'general')}${t.repeat&&t.repeat!=='none'?' · ↻ '+esc(t.repeat):''}${subs.length?` · ${subDone}/${subs.length} steps`:''}</small></div><span class="priority ${t.priority}">${esc(t.priority)}</span><button class="row-icon" data-action="edit-task" data-id="${t.id}">✎</button><button class="row-icon" data-action="delete-task" data-id="${t.id}">×</button></div>`}).join('')||'<div class="empty">no tasks in this view.</div>';
}
function taskForm(t){
 const projectOpts=[['','General'],...state.projects.map(p=>[p.id,p.name])], goalOpts=[['','None'],...state.goals.map(g=>[g.id,`${g.area} · ${g.title}`])];
 const fields=[field('name','title',t?.title||''),field('due','date',t?.date||todayKey(),'date'),selectField('priority','priority',[['low','low'],['medium','medium'],['high','high']],t?.priority||'medium'),selectField('project','projectId',projectOpts,t?.projectId||''),selectField('goal','goalId',goalOpts,t?.goalId||''),selectField('repeat','repeat',[['none','none'],['daily','daily'],['weekly','weekly'],['monthly','monthly']],t?.repeat||'none'),field('subtasks','subtasks',t?.subtasks?.map(x=>x.title).join('\n')||'','text','placeholder="one step per line"')];
 formModal(t?'edit task':'new task',fields,v=>{const subs=String(v.subtasks||'').split(/\n|,/).map(x=>x.trim()).filter(Boolean).map((title,i)=>({id:t?.subtasks?.[i]?.id||uid(),title,done:t?.subtasks?.[i]?.done||false}));const data={title:v.title.trim()||'untitled',date:v.date||todayKey(),priority:v.priority,projectId:v.projectId,goalId:v.goalId,repeat:v.repeat,subtasks:subs};if(t)Object.assign(t,data);else state.tasks.unshift({id:uid(),...data,done:false,created:Date.now()});save();toast(t?'task updated':'task added ♡')});
}
function toggleTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;if(t.done&&t.repeat!=='none'){const next=t.repeat==='daily'?addDays(t.date,1):t.repeat==='weekly'?addDays(t.date,7):addDays(t.date,30);state.tasks.push({...t,id:uid(),date:next,done:false,created:Date.now(),subtasks:(t.subtasks||[]).map(s=>({...s,id:uid(),done:false}))});}save();toast(t.done?'task completed ♡':'task reopened')}
function renderHabits(){
 const days=Array.from({length:7},(_,i)=>addDays(todayKey(),i-6));let total=0,done=0;
 $('#habitGrid').innerHTML=state.habits.map(h=>{const checks=days.map(d=>{const on=!!h.days[d];total++;if(on)done++;return `<button class="habit-day ${on?'on':''}" data-action="toggle-habit" data-id="${h.id}" data-date="${d}" title="${fmtDate(d)}">${on?'✓':''}</button>`}).join('');return `<div class="habit-row"><div class="habit-name"><span>${esc(h.icon)}</span><b>${esc(h.name)}</b><small>${esc(h.frequency)} · ${calcStreak(h)} day streak</small></div><div class="habit-week"><small>7d</small>${checks}</div><button class="row-icon" data-action="edit-habit" data-id="${h.id}">✎</button><button class="row-icon" data-action="delete-habit" data-id="${h.id}">×</button></div>`}).join('')||'<div class="empty">add your first habit.</div>';
 const todayDone=state.habits.filter(h=>h.days[todayKey()]).length; $('#habitToday').textContent=`${todayDone} / ${state.habits.length}`; $('#habitPct').textContent=(total?Math.round(done/total*100):0)+'%'; $('#bestStreak').textContent=Math.max(0,...state.habits.map(calcBestStreak))+' days';
 const px=[];for(let i=34;i>=0;i--){const d=addDays(todayKey(),-i),rate=state.habits.length?state.habits.filter(h=>h.days[d]).length/state.habits.length:0;px.push(`<span class="pixel p${Math.ceil(rate*4)}" title="${fmtDate(d)} · ${Math.round(rate*100)}%"></span>`)}$('#monthPixels').innerHTML=px.join('');
 $('#habitHistory').innerHTML=days.map(d=>`<div><b>${new Intl.DateTimeFormat('en',{weekday:'short'}).format(new Date(d+'T12:00:00'))}</b><span>${state.habits.filter(h=>h.days[d]).length}/${state.habits.length}</span></div>`).join('');
}
function calcStreak(h){let n=0,d=todayKey();while(h.days[d]){n++;d=addDays(d,-1)}return n}
function calcBestStreak(h){let best=0,run=0;for(let i=60;i>=0;i--){const d=addDays(todayKey(),-i);if(h.days[d]){run++;best=Math.max(best,run)}else run=0}return best}
function habitForm(h){formModal(h?'edit habit':'new habit',[field('name','name',h?.name||''),field('icon','icon',h?.icon||'✦'),selectField('frequency','frequency',[['daily','daily'],['3x week','3x week'],['weekly','weekly'],['monthly','monthly']],h?.frequency||'daily')],v=>{if(h)Object.assign(h,{name:v.name.trim()||'habit',icon:v.icon||'✦',frequency:v.frequency});else state.habits.push({id:uid(),name:v.name.trim()||'habit',icon:v.icon||'✦',frequency:v.frequency,target:v.frequency==='3x week'?3:1,days:{}});save();toast(h?'habit updated':'habit added ♡')})}
function toggleHabit(id,date){const h=state.habits.find(x=>x.id===id);if(!h)return;h.days[date]=!h.days[date];save();}

function renderStudy(){
 $('#studyTasks').innerHTML=state.studyTasks.map(t=>`<div class="task-row ${t.done?'done':''}"><input type="checkbox" data-action="toggle-study" data-id="${t.id}" ${t.done?'checked':''}><div class="task-main"><b>${esc(t.title)}</b><small>${esc(t.subject||'General')}</small></div><button class="row-icon" data-action="delete-study" data-id="${t.id}">×</button></div>`).join('')||'<div class="empty">nothing in study queue.</div>';
 $('#subjectGrid').innerHTML=state.subjects.map(s=>`<div class="subject"><div><b>${esc(s.name)}</b><span>${s.progress}%</span></div><div class="progress"><i style="width:${s.progress}%"></i></div><div><button data-action="subject-step" data-id="${s.id}">+5%</button><small>weekly mastery</small></div></div>`).join('');
 $('#notes').innerHTML=state.notes.map(n=>`<div class="note-row"><div><b>${esc(n.title)}</b><small>${esc(n.subject)} · review ${fmtDate(n.due)}</small></div><button class="row-icon" data-action="delete-note" data-id="${n.id}">×</button></div>`).join('')||'<div class="empty">add a revision note.</div>';
 const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];$('#timetable').innerHTML=days.map((d,i)=>{const blocks=state.studyBlocks.filter(b=>b.day===i);return `<div class="time-day"><b>${d}</b><button data-action="add-block" data-day="${i}">+ block</button>${blocks.map(b=>`<span>${esc(b.time)} · ${esc(b.title)} <button class="row-icon" data-action="delete-block" data-id="${b.id}">×</button></span>`).join('')||'<span class="muted">no block</span>'}</div>`}).join('');
 $('#studyTotal').textContent=(state.studyLog[todayKey()]||0)+'m';
}
function studyTaskForm(){formModal('new study task',[field('task','title',''),selectField('subject','subject',[['Pharmacology','Pharmacology'],['Biochemistry','Biochemistry'],['Korean','Korean'],['Anatomy','Anatomy'],['Finance','Finance'],['General','General']],'General')],v=>{state.studyTasks.push({id:uid(),title:v.title.trim()||'study task',subject:v.subject,done:false});save();toast('study task added')})}
function noteForm(){formModal('new revision note',[field('title','title',''),field('subject','subject','General'),field('review date','due',todayKey(),'date'),selectField('interval','push',[['day 1','day 1'],['day 3','day 3'],['day 7','day 7'],['day 14','day 14']], 'day 1')],v=>{state.notes.unshift({id:uid(),title:v.title.trim()||'note',subject:v.subject||'General',due:v.due||todayKey(),push:v.push});save();toast('revision note added')})}
function blockForm(day){formModal('new study block',[field('time','time','09:00','time'),field('activity','title','deep work')],v=>{state.studyBlocks.push({id:uid(),day:Number(day),time:v.time,title:v.title.trim()||'study'});save();toast('study block added')})}

let timer=1500, interval=null, focusDuration=25;
function timerPaint(){const s=Math.max(0,timer),txt=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;['#timer','#homeTimer'].forEach(id=>{if($(id))$(id).textContent=txt})}
function resetTimer(){clearInterval(interval);interval=null;timer=focusDuration*60;timerPaint()}
function startFocus(){if(interval)return;toast('focus started');interval=setInterval(()=>{timer--;timerPaint();if(timer<=0){clearInterval(interval);interval=null;state.studyMinutes+=focusDuration;state.studyLog[todayKey()]=(state.studyLog[todayKey()]||0)+focusDuration;save();timer=focusDuration*60;timerPaint();toast('focus complete ♡')}},1000)}

function renderGlow(){const today=todayKey();$('#routineGrid').innerHTML=state.routines.map(r=>{const key=`${today}:${r.id}`,done=!!state.routineLog[key];return `<div class="routine ${done?'done':''}"><div class="routine-icon">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><small>${esc(r.frequency)}</small><div class="progress"><i style="width:${done?100:0}%"></i></div><button class="routine-done" data-action="routine-done" data-id="${r.id}">${done?'done ♡':'complete today'}</button><button class="row-icon" data-action="edit-routine" data-id="${r.id}">✎</button><button class="row-icon" data-action="delete-routine" data-id="${r.id}">×</button></div>`}).join('');
 const water=state.waterLog[today]||0;$('#waterAmount').textContent=water.toFixed(2)+' L';$('#waterBar').style.width=Math.min(100,water/state.waterGoal*100)+'%';$('#waterGoalLabel').textContent=`goal ${state.waterGoal.toFixed(1)} L`;
 const sleep=state.sleepLogs[today]||{sleep:'00:00',wake:'08:00'};$('#sleepTime').value=sleep.sleep;$('#wakeTime').value=sleep.wake;paintSleep(sleep.sleep,sleep.wake);
 $('#glowLogs').innerHTML=state.glowLogs.map(x=>`<div class="log"><span>${esc(x.text)}</span><small>${esc(x.date)}</small></div>`).join('')||'<div class="empty">your first glow-up log starts here.</div>';
}
function paintSleep(a,b){if(!a||!b)return;let [h,m]=a.split(':').map(Number),[h2,m2]=b.split(':').map(Number),mins=h2*60+m2-(h*60+m);if(mins<0)mins+=1440;$('#sleepDuration').textContent=Math.floor(mins/60)+'h '+mins%60+'m'}
function routineForm(r){formModal(r?'edit routine':'new routine',[field('name','name',r?.name||''),field('icon','icon',r?.icon||'✦'),selectField('frequency','frequency',[['daily','daily'],['3x week','3x week'],['weekly','weekly'],['monthly','monthly']],r?.frequency||'daily')],v=>{if(r)Object.assign(r,{name:v.name.trim()||'routine',icon:v.icon||'✦',frequency:v.frequency});else state.routines.push({id:uid(),name:v.name.trim()||'routine',icon:v.icon||'✦',frequency:v.frequency,target:v.frequency==='3x week'?3:1});save();toast(r?'routine updated':'routine added ♡')})}
function saveSleep(){state.sleepLogs[todayKey()]={sleep:$('#sleepTime').value||'00:00',wake:$('#wakeTime').value||'08:00'};save();toast('sleep log saved')}

function renderFinance(){
 const income=state.entries.filter(e=>e.amount>0).reduce((a,e)=>a+Number(e.amount),0), expense=-state.entries.filter(e=>e.amount<0).reduce((a,e)=>a+Number(e.amount),0);$('#balance').textContent=money(income-expense);const spent=-state.entries.filter(e=>e.date===todayKey()&&e.amount<0).reduce((a,e)=>a+Number(e.amount),0);$('#dailyLimit').textContent=money(state.dailyLimit);$('#limitStatus').textContent=money(Math.max(0,state.dailyLimit-spent))+' left today';
 $('#entries').innerHTML=state.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20).map(e=>`<div class="entry"><div><b>${esc(e.name)}</b><small>${fmtDate(e.date)} · ${esc(e.category)}</small></div><strong class="${e.amount<0?'negative':'positive'}">${e.amount<0?'−':'+'}${money(Math.abs(e.amount)).replace('₺','₺')}</strong><button class="row-icon" data-action="delete-entry" data-id="${e.id}">×</button></div>`).join('')||'<div class="empty">no entries yet.</div>';
 $('#accounts').innerHTML=state.accounts.map(a=>`<div class="account"><div><b>${esc(a.name)}</b><small>${esc(a.type)}</small></div><strong>${money(a.amount)}</strong><button class="row-icon" data-action="edit-account" data-id="${a.id}">✎</button></div>`).join('');
 $('#categories').innerHTML=state.categories.map(c=>{const spentCat=-state.entries.filter(e=>e.category===c.name&&e.amount<0).reduce((a,e)=>a+Number(e.amount),0);const pct=c.limit?Math.min(100,spentCat/c.limit*100):0;return `<div class="category"><div><b>${esc(c.name)}</b><span>${money(spentCat)} / ${money(c.limit)}</span></div><div class="progress"><i style="width:${pct}%"></i></div><button class="row-icon" data-action="edit-category" data-id="${c.id}">✎</button></div>`}).join('');
 renderMoneyChart();
}
function entryForm(kind){const cats=[...state.categories.map(c=>[c.name,c.name]),['income','income'],['other','other']];formModal(kind==='expense'?'log expense':'log income',[field('name','name',kind==='expense'?'coffee':'income'),field('amount','amount','0','number','step="1" min="0"'),field('date','date',todayKey(),'date'),selectField('category','category',cats,kind==='expense'?'food':'income'),selectField('account','accountId',[['','none'],...state.accounts.map(a=>[a.id,a.name])],'')],v=>{const amt=Math.abs(Number(v.amount)||0)*(kind==='expense'?-1:1);state.entries.unshift({id:uid(),name:v.name.trim()||kind,category:v.category,amount:amt,date:v.date||todayKey(),accountId:v.accountId||'',note:''});if(v.accountId){const a=state.accounts.find(x=>x.id===v.accountId);if(a)a.amount+=amt}save();toast(kind+' logged')})}
function accountForm(a){formModal(a?'edit account':'new account',[field('name','name',a?.name||''),field('balance','amount',a?.amount||0,'number'),selectField('type','type',[['cash','cash'],['saving','saving'],['investment','investment']],a?.type||'cash')],v=>{if(a){Object.assign(a,{name:v.name.trim()||'account',amount:Number(v.amount)||0,type:v.type})}else state.accounts.push({id:uid(),name:v.name.trim()||'account',amount:Number(v.amount)||0,type:v.type});save();toast(a?'account updated':'account added')})}
function categoryForm(c){formModal(c?'edit category':'new category',[field('name','name',c?.name||''),field('monthly limit','limit',c?.limit||0,'number')],v=>{if(c)Object.assign(c,{name:v.name.trim()||'category',limit:Number(v.limit)||0});else state.categories.push({id:uid(),name:v.name.trim()||'category',limit:Number(v.limit)||0});save();toast('category saved')})}
function renderMoneyChart(){const months=[];const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=d.toISOString().slice(0,7);const inc=state.entries.filter(e=>e.date.startsWith(key)&&e.amount>0).reduce((a,e)=>a+Number(e.amount),0),exp=-state.entries.filter(e=>e.date.startsWith(key)&&e.amount<0).reduce((a,e)=>a+Number(e.amount),0);months.push({label:new Intl.DateTimeFormat('tr-TR',{month:'short'}).format(d),inc,exp})}const max=Math.max(1,...months.flatMap(x=>[x.inc,x.exp]));$('#moneyChart').innerHTML=months.map(m=>`<div class="bar-col"><div class="bars"><i style="height:${m.inc/max*100}%" title="income ${money(m.inc)}"></i><i style="height:${m.exp/max*100}%" title="expense ${money(m.exp)}"></i></div><small>${esc(m.label)}</small></div>`).join('')+`<div class="chart-legend"><span>income</span><span>expense</span></div>`}

