 const days=['mon','tue','wed','thu','fri','sat','sun'];$('#mealWeek').innerHTML=days.map(d=>{const m=state.meals[d]||{};return `<div class="meal-day"><div><b>${d}</b><button data-action="edit-meal" data-day="${d}">✎</button></div><p>breakfast<br><strong>${esc(m.breakfast||'free choice')}</strong></p><p>lunch<br><strong>${esc(m.lunch||'free choice')}</strong></p><p>dinner<br><strong>${esc(m.dinner||'free choice')}</strong></p></div>`}).join('');
