 $('#ingredients').innerHTML=state.ingredients.map((x,i)=>`<span class="ingredient">${esc(x)} <button data-action="remove-ingredient" data-index="${i}">×</button></span>`).join('')||'<div class="empty">add ingredients to build recommendations.</div>';
