function recipeForm(r){formModal(r?'edit recipe':'new recipe',[field('name','name',r?.name||''),field('emoji','emoji',r?.emoji||'🍽'),field('time','time',r?.time||'20 mins'),field('category','category',r?.category||'main'),field('ingredients','ingredients',(r?.ingredients||[]).join(', '))],v=>{const data={name:v.name.trim()||'recipe',emoji:v.emoji||'🍽',time:v.time||'20 mins',category:v.category||'main',ingredients:v.ingredients.split(',').map(x=>x.trim()).filter(Boolean)};if(r)Object.assign(r,data);else state.recipes.unshift({id:uid(),...data,uses:0});save();toast(r?'recipe updated':'recipe added')})}
