function renderGoals(){
 $('#goalGrid').innerHTML=state.goals.map((g,i)=>{const linked=state.projects.filter(p=>p.goalId===g.id);const derived=linked.length?Math.round(linked.reduce((a,p)=>a+p.progress,0)/linked.length):g.progress;return `<div class="goal"><span>0${i+1} · ${esc(g.area)}</span><h2>${esc(g.title)}</h2><div class="progress"><i style="width:${derived}%"></i></div><div class="goal-bottom"><small>${derived}% · ${linked.length} linked projects</small><button class="soft-btn" data-action="goal-step" data-id="${g.id}">+ milestone</button><button class="row-icon" data-action="edit-goal" data-id="${g.id}">✎</button></div></div>`}).join('')||'<div class="empty">define your first future-self goal.</div>';
}
function goalForm(g){formModal(g?'edit goal':'new goal',[field('area','area',g?.area||''),field('goal','title',g?.title||''),field('progress','progress',g?.progress||0,'number','min="0" max="100"')],v=>{const data={area:v.area.trim()||'General',title:v.title.trim()||'future goal',progress:Math.max(0,Math.min(100,Number(v.progress)||0))};if(g)Object.assign(g,data);else state.goals.push({id:uid(),...data});save();toast('goal saved ✦')})}
function renderProjects(){
 $('#projectGrid').innerHTML=state.projects.map(p=>{const tasks=state.tasks.filter(t=>t.projectId===p.id),done=tasks.filter(t=>t.done).length;const derived=tasks.length?Math.round(done/tasks.length*100):p.progress;const goal=state.goals.find(g=>g.id===p.goalId);return `<div class="project"><div><span>${esc(goal?.area||'unlinked goal')}</span><h2>${esc(p.name)}</h2></div><strong>${derived}%</strong><div class="progress"><i style="width:${derived}%"></i></div><small>${done}/${tasks.length} linked tasks${tasks.length?' · auto progress':''}</small><div><button class="soft-btn" data-action="project-step" data-id="${p.id}">+ milestone</button><button class="row-icon" data-action="edit-project" data-id="${p.id}">✎</button><button class="row-icon" data-action="delete-project" data-id="${p.id}">×</button></div></div>`}).join('')||'<div class="empty">turn a goal into a finite project.</div>';
}
function projectForm(p){formModal(p?'edit project':'new project',[field('project name','name',p?.name||''),selectField('linked goal','goalId',[['','none'],...state.goals.map(g=>[g.id,`${g.area} · ${g.title}`])],p?.goalId||''),field('manual progress','progress',p?.progress||0,'number','min="0" max="100"')],v=>{const data={name:v.name.trim()||'project',goalId:v.goalId||'',progress:Math.max(0,Math.min(100,Number(v.progress)||0))};if(p)Object.assign(p,data);else state.projects.push({id:uid(),...data});save();toast('project saved')})}

function renderJournal(){$('#journalList').innerHTML=state.journal.map(j=>`<article class="journal-entry"><div><span>${esc(j.mood||'good')}</span><small>${esc(j.date)}</small></div><h3>${esc(j.title||'untitled')}</h3><p>${esc(j.body)}</p><button class="row-icon" data-action="delete-journal" data-id="${j.id}">×</button></article>`).join('')||'<div class="empty">your journal starts here.</div>'}
let journalMood='good';
function saveJournal(){const title=$('#journalTitle').value.trim(),body=$('#journalBody').value.trim();if(!title&&!body)return toast('write something first');state.journal.unshift({id:uid(),date:fmtDate(todayKey()),title,body,mood:journalMood});$('#journalTitle').value='';$('#journalBody').value='';save();toast('journal saved ♡')}

function renderDashboard(){
 const days=['sun','mon','tue','wed','thu','fri','sat'], imgs=['hobbies','money','study','korean','body','hobbies','korean'], caps=[['reset plan','slow down'],['focus study','no excuses'],['progress','small wins'],['don’t overthink','just do it'],['trust the process','keep going'],['almost there','keep going'],['rest','reflect']];$('#weekOverview').innerHTML=days.map((d,i)=>`<button class="week-card" data-action="week-day" data-day="${d}"><img src="assets/${imgs[i]}.jpeg"><b>${d}</b><p>${caps[i][0]}</p><small>${caps[i][1]}</small></button>`).join('');
 const d0=new Date(),year=d0.getFullYear(),month=d0.getMonth(),first=new Date(year,month,1),start=(first.getDay()+6)%7,daysIn=new Date(year,month+1,0).getDate();let cells='';for(let i=0;i<42;i++){const n=i-start+1;if(n<1||n>daysIn){cells+='<div class="month-cell muted"></div>';continue}const d=`${year}-${String(month+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,tasks=state.tasks.filter(t=>t.date===d&&!t.done).length;cells+=`<button class="month-cell" data-action="month-day" data-date="${d}"><small>${n}</small>${tasks?`<em>${tasks} task${tasks>1?'s':''}</em>`:''}</button>`}$('#monthOverview').innerHTML=`<div class="month-top"><b>${new Intl.DateTimeFormat('en',{month:'long',year:'numeric'}).format(d0)}</b><span>tasks + habits + study</span></div><div class="month-grid">${cells}</div>`;
 const all=state.tasks.length, td=state.tasks.filter(t=>t.done).length,pct=all?Math.round(td/all*100):0;$('#focusPct').textContent=pct+'%';$('#focusBar').style.width=pct+'%';$('#focusTasks').textContent=state.tasks.filter(t=>!t.done).length;$('#focusHabits').textContent=state.habits.filter(h=>!h.days[todayKey()]).length;$('#focusStudy').textContent=(state.studyLog[todayKey()]||0)+'m';$('#glanceHabits').textContent=`${state.habits.filter(h=>h.days[todayKey()]).length}/${state.habits.length}`;$('#glanceStudy').textContent=(state.studyLog[todayKey()]||0)+'m';$('#glanceWater').textContent=(state.waterLog[todayKey()]||0).toFixed(1)+' L';$('#glanceSpend').textContent=money(-state.entries.filter(e=>e.date===todayKey()&&e.amount<0).reduce((a,e)=>a+Number(e.amount),0));$('#weekScore').textContent=`${state.tasks.filter(t=>t.done).length} tasks done`;$('#monthScore').textContent=`${state.goals.filter(g=>g.progress>=50).length} goals ≥ 50%`;$('#prioritiesList').innerHTML=state.priorities.map((p,i)=>{const t=state.tasks.find(x=>x.title===p);return `<label><input type="checkbox" data-action="priority" data-index="${i}" ${t?.done?'checked':''}><span>${esc(p)}</span></label>`}).join('');
 $('#todayDate').textContent=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long'}).format(new Date());
}
function checkinModal(){openModal(`<span class="eyebrow">DAILY CHECK-IN</span><h2>How are you actually doing?</h2><form id="checkinForm"><div class="form-grid">${selectField('mood','mood',[['calm','calm'],['good','good'],['focused','focused'],['tired','tired'],['overwhelmed','overwhelmed']],'good')}${field('energy 1–10','energy','7','number','min="1" max="10"')}${field('sleep hours','sleep',String(Math.round(getSleepDuration()/60)),'number','min="0" max="24"')}${field('one thing','note','','text','placeholder="what matters most today?"')}</div><button class="primary full" type="submit">save check-in</button></form>`);$('#checkinForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target).entries());state.checkins.unshift({id:uid(),date:todayKey(),...v});save();closeModal();toast('check-in saved ☀')}}
function getSleepDuration(){const x=state.sleepLogs[todayKey()]||{sleep:'00:00',wake:'08:00'};let [h,m]=x.sleep.split(':').map(Number),[h2,m2]=x.wake.split(':').map(Number),mins=h2*60+m2-(h*60+m);if(mins<0)mins+=1440;return mins}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='elif-os-backup.json';a.click();URL.revokeObjectURL(a.href);toast('backup exported')}
function importData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{state=migrate(JSON.parse(r.result));save();toast('backup imported ♡')}catch{toast('invalid backup')}};r.readAsText(file)}
function settingsModal(){openModal(`<span class="eyebrow">ELIF OS</span><h2>system controls</h2><p class="muted">Local-first with optional cloud sync. Export a backup anytime.</p><div class="quick-modal"><button id="syncSettingsBtn">☁ cloud sync</button><button id="exportBtn">export backup</button><button id="importBtn">import backup</button><button id="resetBtn">reset demo data</button></div><input type="file" id="importFile" accept="application/json" hidden><div id="syncStatus" class="sync-status"></div>`);$('#syncSettingsBtn').onclick=syncModal;$('#exportBtn').onclick=exportData;$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=e=>importData(e.target.files[0]);$('#resetBtn').onclick=()=>{if(confirm('Reset ELIF OS demo data?')){state=migrate(JSON.parse(JSON.stringify(seed)));save();closeModal();toast('demo data restored')}};renderSyncStatus()}
function quickMenu(){openModal(`<span class="eyebrow">QUICK ADD</span><h2>What are we adding?</h2><div class="quick-modal">${[['task','✓ task'],['habit','✿ habit'],['expense','₺ expense'],['income','₺ income'],['goal','✦ goal'],['project','◇ project'],['recipe','🍞 recipe'],['journal','♡ journal'],['routine','⌁ routine'],['grocery','🛒 grocery']].map(x=>`<button data-quick="${x[0]}">${x[1]}</button>`).join('')}</div>`);$$('[data-quick]').forEach(b=>b.onclick=()=>{closeModal();quickAction(b.dataset.quick)})}
function quickAction(type){({task:()=>taskForm(),habit:()=>habitForm(),expense:()=>entryForm('expense'),income:()=>entryForm('income'),goal:()=>goalForm(),project:()=>projectForm(),recipe:()=>recipeForm(),journal:()=>nav('journal'),routine:()=>routineForm(),grocery:()=>formModal('new grocery item',[field('item','name','')],v=>{state.grocery.push({id:uid(),name:v.name.trim()||'item',done:false});save();toast('grocery item added')})}[type]||(()=>{}))()}

function handleAction(a,el){const id=el.dataset.id;
 if(a==='toggle-task')toggleTask(id); else if(a==='delete-task'){state.tasks=state.tasks.filter(x=>x.id!==id);save();toast('task deleted')} else if(a==='edit-task')taskForm(state.tasks.find(x=>x.id===id));
 else if(a==='toggle-habit')toggleHabit(id,el.dataset.date); else if(a==='edit-habit')habitForm(state.habits.find(x=>x.id===id)); else if(a==='delete-habit'){state.habits=state.habits.filter(x=>x.id!==id);save();}
 else if(a==='toggle-study'){const t=state.studyTasks.find(x=>x.id===id);if(t)t.done=!t.done;save()} else if(a==='delete-study'){state.studyTasks=state.studyTasks.filter(x=>x.id!==id);save()}
 else if(a==='subject-step'){const s=state.subjects.find(x=>x.id===id);if(s)s.progress=Math.min(100,s.progress+5);save()}
 else if(a==='delete-note'){state.notes=state.notes.filter(x=>x.id!==id);save()} else if(a==='add-block')blockForm(el.dataset.day); else if(a==='delete-block'){state.studyBlocks=state.studyBlocks.filter(x=>x.id!==id);save()}
 else if(a==='routine-done'){const key=`${todayKey()}:${id}`;state.routineLog[key]=!state.routineLog[key];save()} else if(a==='edit-routine')routineForm(state.routines.find(x=>x.id===id)); else if(a==='delete-routine'){state.routines=state.routines.filter(x=>x.id!==id);save()}
 else if(a==='delete-entry'){state.entries=state.entries.filter(x=>x.id!==id);save()} else if(a==='edit-account')accountForm(state.accounts.find(x=>x.id===id));
 else if(a==='edit-category')categoryForm(state.categories.find(x=>x.id===id));
 else if(a==='recommend-recipe'){const r=state.recipes.find(x=>x.id===id);if(r)r.uses=(r.uses||0)+1;save();toast('recipe added to this week')}
 else if(a==='edit-recipe')recipeForm(state.recipes.find(x=>x.id===id)); else if(a==='delete-recipe'){state.recipes=state.recipes.filter(x=>x.id!==id);save()}
 else if(a==='toggle-grocery'){const g=state.grocery.find(x=>x.id===id);if(g)g.done=!g.done;save()} else if(a==='delete-grocery'){state.grocery=state.grocery.filter(x=>x.id!==id);save()}
 else if(a==='remove-ingredient'){state.ingredients.splice(Number(el.dataset.index),1);save()}
 else if(a==='goal-step'){const g=state.goals.find(x=>x.id===id);if(g)g.progress=Math.min(100,g.progress+5);save();toast('goal milestone +5%')}
 else if(a==='edit-goal')goalForm(state.goals.find(x=>x.id===id));
 else if(a==='project-step'){const p=state.projects.find(x=>x.id===id);if(p)p.progress=Math.min(100,p.progress+5);save();toast('project milestone +5%')} else if(a==='edit-project')projectForm(state.projects.find(x=>x.id===id)); else if(a==='delete-project'){state.projects=state.projects.filter(x=>x.id!==id);state.tasks.forEach(t=>{if(t.projectId===id)t.projectId=''});save()}
 else if(a==='delete-journal'){state.journal=state.journal.filter(x=>x.id!==id);save()}
 else if(a==='toggle-automation'){const x=state.automations.find(x=>x.id===id);if(x)x.enabled=el.checked;save()} else if(a==='edit-automation')automationForm(state.automations.find(x=>x.id===id)); else if(a==='delete-automation'){state.automations=state.automations.filter(x=>x.id!==id);save()}
 else if(a==='week-day'){window.taskFilter='all';$$('[data-task-filter]').forEach(x=>x.classList.toggle('active',x.dataset.taskFilter==='all'));nav('tasks');renderTasks();}
 else if(a==='month-day'){window.taskFilter='all';nav('tasks');$('#taskSearch').value='';renderTasks();toast(`${fmtDate(el.dataset.date)} selected`)}
 else if(a==='priority'){const p=state.priorities[Number(el.dataset.index)],t=state.tasks.find(x=>x.title===p);if(t)t.done=el.checked;else if(el.checked)state.tasks.push({id:uid(),title:p,date:todayKey(),priority:'medium',done:true,projectId:'',goalId:'',repeat:'none',subtasks:[],created:Date.now()});save()}
}

