/* ---------- Cloud Sync + Automation Engine (v1.4) ---------- */
function syncConfig(){try{const saved=JSON.parse(localStorage.getItem(SYNC_KEY)||'{}');const defaults=window.ELIF_OS_CONFIG||{};return {url:saved.url||defaults.supabaseUrl||'',anonKey:saved.anonKey||defaults.supabasePublishableKey||''}}catch{return window.ELIF_OS_CONFIG?{url:window.ELIF_OS_CONFIG.supabaseUrl||'',anonKey:window.ELIF_OS_CONFIG.supabasePublishableKey||''}:{}}}
function syncSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
function setSyncConfig(v){localStorage.setItem(SYNC_KEY,JSON.stringify(v))}
function setSyncSession(v){if(v)localStorage.setItem(SESSION_KEY,JSON.stringify(v));else localStorage.removeItem(SESSION_KEY)}
function supabaseHeaders(token){const c=syncConfig();return {'apikey':c.anonKey,'Authorization':'Bearer '+(token||c.anonKey),'Content-Type':'application/json','Prefer':'return=representation'}}
function validSupabase(){const c=syncConfig();return /^https:\/\/[^\s]+/.test(c.url||'') && (c.anonKey||'').length>20}
async function authRequest(path,body){const c=syncConfig();if(!validSupabase())throw new Error('Supabase URL and anon key are required');const r=await fetch(c.url.replace(/\/$/,'')+'/auth/v1/'+path,{method:'POST',headers:supabaseHeaders(),body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.msg||j.error_description||j.message||'Authentication failed');return j}
async function signUp(email,password){const j=await authRequest('signup',{email,password});if(j.access_token){setSyncSession(j);toast('cloud account created ♡');await cloudSyncNow()}else toast('account created — check your email if confirmation is enabled')}
async function signIn(email,password){const j=await authRequest('token?grant_type=password',{email,password});setSyncSession(j);toast('signed in ♡');await cloudSyncNow()}
function signOut(){setSyncSession(null);toast('signed out — local mode remains available');renderSyncStatus()}
async function fetchCloud(){const c=syncConfig(),s=syncSession();if(!s)throw new Error('Sign in first');const r=await fetch(c.url.replace(/\/$/,'')+'/rest/v1/elif_state?select=payload,updated_at&user_id=eq.'+encodeURIComponent(s.user.id),{headers:supabaseHeaders(s.access_token)});if(!r.ok)throw new Error('Could not read cloud data');const rows=await r.json();return rows[0]||null}
async function pushCloud(){const c=syncConfig(),s=syncSession();if(!s)throw new Error('Sign in first');const body={user_id:s.user.id,payload:state,updated_at:new Date().toISOString()};const r=await fetch(c.url.replace(/\/$/,'')+'/rest/v1/elif_state?on_conflict=user_id',{method:'POST',headers:{...supabaseHeaders(s.access_token),'Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(body)});if(!r.ok)throw new Error('Could not upload cloud data')}
async function cloudSyncNow(){if(!validSupabase()){renderSyncStatus();return}const s=syncSession();if(!s){renderSyncStatus();return}try{const cloud=await fetchCloud();if(cloud?.payload){const localTime=Number(localStorage.getItem('elif-os-last-write')||0);const cloudTime=Date.parse(cloud.updated_at||0)||0;if(cloudTime>localTime){state=migrate(cloud.payload);localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem('elif-os-last-write',String(cloudTime));render();toast('cloud data downloaded ♡')}}await pushCloud();localStorage.setItem('elif-os-last-write',String(Date.now()));toast('synced across devices ♡');renderSyncStatus()}catch(e){console.warn(e);toast('sync failed: '+e.message);renderSyncStatus(e.message)}}
let syncTimer=null;
function queueCloudSync(){clearTimeout(syncTimer);if(!syncSession())return;syncTimer=setTimeout(()=>cloudSyncNow(),900)}
function renderSyncStatus(err=''){const el=$('#syncStatus');if(!el)return;const c=syncConfig(),s=syncSession();el.textContent=err?'sync error: '+err:s?(c.url?'cloud connected · '+(s.user?.email||'signed in'):'signed in'):c.url?'configured · sign in to sync':'local-only';el.className='sync-status '+(err?'error':s?'ok':'')}
function syncModal(){const c=syncConfig(),s=syncSession();openModal(`<span class="eyebrow">ELIF OS</span><h2>cloud sync</h2><p class="muted">Free Supabase sync keeps one ELIF OS database across iPhone, iPad and PC. Your password is sent directly to Supabase.</p><div class="form-grid"><label>Supabase project URL<input id="supabaseUrl" value="${esc(c.url||'')}" placeholder="https://xxxx.supabase.co"></label><label>Supabase anon/publishable key<input id="supabaseKey" value="${esc(c.anonKey||'')}" placeholder="eyJ..."></label><label>email<input id="syncEmail" type="email" value="${esc(s?.user?.email||'')}"></label><label>password<input id="syncPassword" type="password" placeholder="••••••••"></label></div><div class="sync-actions"><button class="soft-btn" id="saveSyncCfg">save connection</button><button class="primary" id="signInSync">sign in</button><button class="soft-btn" id="signUpSync">create account</button><button class="soft-btn" id="syncNow">sync now</button><button class="soft-btn" id="signOutSync">sign out</button></div><div id="syncStatus" class="sync-status"></div><p class="tiny muted">First-time setup also needs the SQL in <b>supabase-schema.sql</b> from the ZIP.</p>`);$('#saveSyncCfg').onclick=()=>{setSyncConfig({url:$('#supabaseUrl').value.trim(),anonKey:$('#supabaseKey').value.trim()});renderSyncStatus();toast('connection saved')};$('#signInSync').onclick=async()=>{try{setSyncConfig({url:$('#supabaseUrl').value.trim(),anonKey:$('#supabaseKey').value.trim()});await signIn($('#syncEmail').value.trim(),$('#syncPassword').value)}catch(e){toast(e.message)}};$('#signUpSync').onclick=async()=>{try{setSyncConfig({url:$('#supabaseUrl').value.trim(),anonKey:$('#supabaseKey').value.trim()});await signUp($('#syncEmail').value.trim(),$('#syncPassword').value)}catch(e){toast(e.message)}};$('#syncNow').onclick=cloudSyncNow;$('#signOutSync').onclick=signOut;renderSyncStatus()}
function automationDue(a,now){if(!a.enabled)return false;const last=state.automationLog[a.id]||'';const date=now.toISOString().slice(0,10);if(a.type==='daily-checkin'||a.type==='weekly-review'){if(last===date)return false;const h=now.getHours(),m=now.getMinutes();if(a.time && (h!==Number(a.time.split(':')[0])||m<Number(a.time.split(':')[1])||m>Number(a.time.split(':')[1])+1))return false;if(a.type==='weekly-review'&&now.getDay()!==1)return false;return true}if(a.type==='overdue'){return state.tasks.some(t=>!t.done&&t.date<date)&&last!==date}if(a.type==='review-due'){return state.notes.some(n=>n.due<=date)&&last!==date}return false}
function fireAutomation(a,now){state.automationLog[a.id]=now.toISOString().slice(0,10);let msg='';if(a.type==='daily-checkin')msg='Daily check-in: open ELIF OS and choose your top 3. ♡';if(a.type==='weekly-review')msg='Weekly review: look back, reset priorities, plan the week.';if(a.type==='overdue')msg='You have overdue tasks. Clear one before adding more.';if(a.type==='review-due')msg='Spaced-repetition reviews are due today.';if('Notification' in window&&Notification.permission==='granted')new Notification('ELIF OS',{body:msg});toast(msg);localStorage.setItem(KEY,JSON.stringify(state));render()}
function runAutomations(){const now=new Date();(state.automations||[]).forEach(a=>{if(automationDue(a,now))fireAutomation(a,now)});renderAutomationStatus?.()}
function automationForm(a){const types=[['daily-checkin','Daily check-in'],['weekly-review','Weekly review'],['overdue','Overdue task reminder'],['review-due','Study review reminder']];formModal(a?'edit automation':'new automation',[field('name','name',a?.name||''),selectField('type','type',types,a?.type||'daily-checkin'),field('time','time',a?.time||'20:00','time')],v=>{const obj={id:a?.id||uid(),name:v.name.trim()||'automation',type:v.type,time:v.time||'20:00',enabled:a?.enabled!==false};if(a)Object.assign(a,obj);else state.automations.push(obj);save();toast('automation saved')})}
function renderAutomationStatus(){const el=$('#automationList');if(!el)return;el.innerHTML=(state.automations||[]).map(a=>`<div class="automation-row"><div><b>${esc(a.name)}</b><small>${esc(a.type)} · ${esc(a.time||'event-based')}</small></div><label class="switch"><input type="checkbox" data-action="toggle-automation" data-id="${a.id}" ${a.enabled?'checked':''}><span></span></label><button class="row-icon" data-action="edit-automation" data-id="${a.id}">✎</button><button class="row-icon" data-action="delete-automation" data-id="${a.id}">×</button></div>`).join('')||'<div class="empty">no automations yet.</div>';renderSyncStatus()}

function render(){renderTasks();renderHabits();renderStudy();renderGlow();renderFinance();renderMeals();renderGoals();renderProjects();renderJournal();renderDashboard();renderAutomationStatus();if($('#brainDump'))$('#brainDump').value=state.brain||'';timerPaint();}
render();
runAutomations();
if(syncSession()) setTimeout(cloudSyncNow,1200);
setInterval(runAutomations,60000);
